-- FO-10 part 2 (P-773; AG-2-85 rule 5): round robin gives the next lead to the person given one least recently. Two
-- additive columns on fo_assignment_rule (FO-10 part 1's table): the rule's turn count and each person's last turn.
-- Generated by `prisma migrate diff`, then the rule Prisma cannot say, below.

-- AlterTable
ALTER TABLE "fo_assignment_rule" ADD COLUMN     "turn_no" INTEGER NOT NULL DEFAULT 0,
ADD COLUMN     "turns" JSONB NOT NULL DEFAULT '{}';


-- turns is an object (staff id → the turn number that person last got); turn_no never goes below 0.
ALTER TABLE "fo_assignment_rule" ADD CONSTRAINT "fo_assignment_rule_turns_check" CHECK (jsonb_typeof("turns") = 'object' AND "turn_no" >= 0);
